"""Analyst: every number in an answer is computed in code, never generated by a model.

Two jobs:
  1. derive facts from SQL results (top/bottom, spread, change over time, shares)
  2. find what distinguishes a set of reviews from the rest, with the weighted
     log-odds ratio and an informative Dirichlet prior (Monroe, Colaresi & Quinn 2008):

     delta_w = log((y_w^i + a_w) / (n^i + a_0 - y_w^i - a_w)) - log((y_w^j + a_w) / (n^j + a_0 - y_w^j - a_w))
     z_w     = delta_w / sqrt(1/(y_w^i + a_w) + 1/(y_w^j + a_w))

     The z-score down-weights rare words that look distinctive only by chance, which
     plain frequency or TF-IDF comparisons get wrong on small samples.
"""
from __future__ import annotations

import math
from collections import Counter

from cortex.core.models import Evidence
from cortex.retrieval.index import tokenize

STOP_EXTRA = set("i my me we our you your they them very after before when what have has had will would "
                 "just one two all also only so but too did do does got came".split())


def _num(v):
    return float(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else None


def derive_facts(columns: list[str], rows: list[tuple], metric: str | None) -> list[Evidence]:
    out: list[Evidence] = []
    if not rows:
        return out
    if len(columns) == 1 and len(rows) == 1:
        out.append(Evidence(id="calc:value", kind="computed", content=f"{metric or columns[0]} = {rows[0][0]}",
                            data={"value": _num(rows[0][0])}))
        return out
    if len(columns) == 3 and columns[1] in ("month", "quarter", "year"):
        # one series per group (e.g. company x quarter): a trend fact for each group
        groups: dict[str, list[tuple[str, float]]] = {}
        for r in rows:
            if _num(r[2]) is not None:
                groups.setdefault(str(r[0]), []).append((str(r[1]), _num(r[2])))
        for g, pts in groups.items():
            if len(pts) >= 2:
                (l0, v0), (l1, v1) = pts[0], pts[-1]
                pct = ((v1 - v0) / v0 * 100) if v0 else None
                out.append(Evidence(id=f"calc:trend:{g}", kind="computed",
                                    content=f"{g}: {columns[-1]} went from {v0} ({l0}) to {v1} ({l1}); change {v1 - v0:+.4g}"
                                            + (f" ({pct:+.1f}%)" if pct is not None else ""),
                                    data={"group": g, "first": v0, "last": v1, "first_label": l0, "last_label": l1,
                                          "change": round(v1 - v0, 4), "pct_change": round(pct, 1) if pct is not None else None}))
        return out
    if len(columns) >= 2:
        label_idx, val_idx = 0, len(columns) - 1
        vals = [(str(r[label_idx]), _num(r[val_idx])) for r in rows if _num(r[val_idx]) is not None]
        if not vals:
            return out
        is_time = columns[0] in ("month", "quarter", "year")
        if is_time and len(vals) >= 2:
            (l0, v0), (l1, v1) = vals[0], vals[-1]
            change = v1 - v0
            pct = (change / v0 * 100) if v0 else None
            peak = max(vals, key=lambda x: x[1])
            out.append(Evidence(id="calc:trend", kind="computed",
                                content=f"{columns[-1]} went from {v0} ({l0}) to {v1} ({l1}); change {change:+.4g}"
                                        + (f" ({pct:+.1f}%)" if pct is not None else "") + f"; peak {peak[1]} in {peak[0]}",
                                data={"first": v0, "last": v1, "change": round(change, 4),
                                      "pct_change": round(pct, 1) if pct is not None else None,
                                      "peak": peak[1], "peak_label": peak[0]}))
        else:
            hi = max(vals, key=lambda x: x[1])
            lo = min(vals, key=lambda x: x[1])
            mean = sum(v for _, v in vals) / len(vals)
            ratio = (hi[1] / lo[1]) if lo[1] else None
            out.append(Evidence(id="calc:spread", kind="computed",
                                content=f"highest {hi[0]} = {hi[1]}; lowest {lo[0]} = {lo[1]}; mean of {len(vals)} groups = {mean:.4g}"
                                        + (f"; highest is {ratio:.2f}x the lowest" if ratio else ""),
                                data={"top": hi[1], "top_label": hi[0], "bottom": lo[1], "bottom_label": lo[0],
                                      "mean": round(mean, 4), "ratio": round(ratio, 2) if ratio else None,
                                      "groups": len(vals)}))
    return out


def distinctive_terms(target: list[str], background: list[str], k: int = 6, prior_scale: float = 0.01,
                      min_count: int = 3) -> list[tuple[str, float, int]]:
    """Weighted log-odds with informative Dirichlet prior. Returns (term, z, count) sorted by z."""
    def grams(texts):
        c = Counter()
        for t in texts:
            toks = [w for w in tokenize(t, light=True) if w not in STOP_EXTRA and len(w) > 2]
            c.update(toks)
            c.update(f"{a} {b}" for a, b in zip(toks, toks[1:]))
        return c
    yi, yj = grams(target), grams(background)
    prior = yi + yj
    a0_total = sum(prior.values())
    a = {w: prior_scale * prior[w] * 1000 / max(a0_total, 1) + 0.01 for w in prior}
    a0 = sum(a.values())
    ni, nj = sum(yi.values()), sum(yj.values())
    scored = []
    for w, cnt in yi.items():
        if cnt < min_count:
            continue
        aw = a[w]
        li = math.log((yi[w] + aw) / (ni + a0 - yi[w] - aw))
        lj = math.log((yj[w] + aw) / (nj + a0 - yj[w] - aw))
        z = (li - lj) / math.sqrt(1 / (yi[w] + aw) + 1 / (yj[w] + aw))
        scored.append((w, round(z, 2), cnt))
    scored.sort(key=lambda x: -x[1])
    # prefer bigrams over their own unigrams
    out, seen = [], set()
    for w, z, c in scored:
        if any(w in s.split() for s in seen if " " in s):
            continue
        out.append((w, z, c))
        seen.add(w)
        if len(out) >= k:
            break
    return out
